<?php
namespace App\Models\FbMarketing;
use Illuminate\Database\Eloquent\Model;
class FbmAd extends Model{protected $table='fbm_ads';protected $guarded=[];protected $casts=['is_available'=>'boolean','last_seen_at'=>'datetime','provider_created_time'=>'datetime','provider_updated_time'=>'datetime'];protected $hidden=['provider_sync_key','provider_creative_sync_key'];public function connection(){return $this->belongsTo(FbmConnection::class,'fbm_connection_id');}public function adAccount(){return $this->belongsTo(FbmAdAccount::class,'fbm_ad_account_id');}public function campaign(){return $this->belongsTo(FbmCampaign::class,'fbm_campaign_id');}public function adSet(){return $this->belongsTo(FbmAdSet::class,'fbm_ad_set_id');}public function creative(){return $this->belongsTo(FbmCreative::class,'fbm_creative_id');}public function toSafeSummary():array{return ['id'=>(int)$this->id,'connection_name'=>optional($this->connection)->connection_name,'ad_account_name'=>optional($this->adAccount)->asset_name,'campaign_name'=>optional($this->campaign)->name,'ad_set_name'=>optional($this->adSet)->name,'creative_name'=>optional($this->creative)->name,'name'=>$this->name,'configured_status'=>$this->configured_status,'effective_status'=>$this->effective_status,'is_available'=>(bool)$this->is_available,'last_seen_at'=>optional($this->last_seen_at)->toDateTimeString()];}}
